"""Build the five-level practice course from explicit fictional scenario facts.
No live awarding-body papers, qualification claims or automatic productive-skill grades.
"""
from pathlib import Path
import json,hashlib
ROOT=Path(__file__).resolve().parents[2]
# purpose, organisation, task, item, contact, options and genuine trade-off
SCENARIOS=[
 ('Personal information','Park Learning Centre','update your contact details','reference number','Mina','online form','reception appointment','The online form is available at any time. An appointment gives you help checking the details.','You have changed your address and need help correcting your record.'),
 ('Public information','Westfield Library','renew your library membership','library card','Omar','self-service desk','staffed desk','The self-service desk has a shorter queue. Staff can help with lost cards.','Your library card is missing and you want to renew your membership.'),
 ('Appointments','Riverside Clinic','confirm your appointment','appointment letter','Sara','telephone confirmation','reception visit','A telephone call avoids a journey. Reception can check documents in person.','Your appointment letter has the wrong contact number and you want it corrected.'),
 ('Housing and community','King Street Housing Office','report a repair','repair reference','Ben','online repair report','telephone report','An online report lets you attach a photo. The telephone team can help explain the problem.','A window does not close properly and you need to report the fault.'),
 ('Shopping and services','Market Street Repairs','arrange a repair for a faulty kettle','purchase receipt','Asha','morning collection','afternoon drop-off','Collection saves you carrying the item. Drop-off lets you speak to the repair team.','Your kettle has stopped working and you want the repair team to inspect it.'),
 ('Travel and directions','Town Transport Office','plan a journey to college','route number','Leo','direct bus','bus and train','The direct bus needs no change. The bus and train route is faster but needs a connection.','You start a college course and need a route you can follow reliably.'),
 ('Health and wellbeing','Meadow Community Centre','book a walking group session','booking reference','Nadia','morning walk','afternoon walk','The morning walk uses a shorter route. The afternoon walk has a longer rest stop.','You want to join a walking group and ask about the route before booking.'),
 ('Workplace communication','Northside Workshop','confirm your training session','staff number','Tom','online training','workshop training','Online training avoids travel. Workshop training includes supervised practice.','Your work timetable has changed and you need a different training session.'),
 ('Education and training','Oak Adult College','choose an English class','course reference','Lina','weekday class','Saturday class','The weekday class meets twice a week. The Saturday class meets once for a longer session.','You work on weekdays and want an English class you can attend regularly.'),
 ('Messages and digital access','Central Advice Hub','request help with an application','application reference','Ali','video appointment','office appointment','A video appointment avoids travel. An office appointment provides access to a computer.','You do not have a reliable internet connection and need help with an application.')
]
STAGES=['Find key information','Understand order and instructions','Explain reasons','Compare options','Solve a problem','Consider evidence','Work independently']
LEVELS=['Entry Level 1','Entry Level 2','Entry Level 3','Level 1','Level 2']
DAYS=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Monday']
def mc(prompt,correct,wrong,explanation):
 options=[correct]+[x for x in wrong if x!=correct]
 assert len(options)==len(set(options)) and len(options)>=3
 rotation=int(hashlib.sha256(prompt.encode()).hexdigest()[:4],16)%len(options)
 options=options[rotation:]+options[:rotation]
 return {'kind':'choice','prompt':prompt,'options':options[:4],'answer':correct,'explanation':explanation}
def reflection(prompt,model):return {'kind':'response','prompt':prompt,'model':model}
def build(n,stage,topic,sec,old):
 title,org,action,item,person,opt1,opt2,trade,problem=SCENARIOS[topic]
 my_action=action.replace('your ','my ')
 day=DAYS[stage-1]; hour=9+((topic+stage)%7);time=f'{hour}:30';room=1+((topic+stage)%8);deadline=DAYS[(stage+2)%7]
 purpose=f'To explain how to {action}.'
 notice=f'{org}\n{action[0].upper()+action[1:]}\nCome on {day} at {time}.\nGo to Room {room}.\nBring your {item}.\nAsk {person} for help.'
 if n==1: text=notice
 elif n==2:text=f'{org} — information\n\nPlease come on {day} at {time} to {action}. Bring your {item} and go to Room {room}. First, speak to {person}. Then check your details before you leave. If you cannot come, contact the office before {deadline}.\n\nYou can choose the {opt1} or the {opt2}. {trade}'
 elif n==3:text=f'{org}: making arrangements\n\n{problem} The office has offered a session on {day} at {time} in Room {room}. You should bring your {item} so that {person} can find the correct record. If you cannot attend, contact the office before {deadline}; this allows the place to be offered to someone else.\n\nThere are two ways to {action}: the {opt1} or the {opt2}. {trade} Before choosing, consider your travel time, access to equipment and the support you need.\n\nAfter the session, check the written summary. Contact the office if a detail is wrong rather than assuming it will be corrected automatically.'
 else:
  topic_phrase=title.lower()
  text=f'{org}: reviewing access to support\n\n{problem} This fictional case illustrates a question facing the organisation: how can it make it easier for people to {action.replace('your ','their ')} while retaining support for those who need it?\n\nThe current offer is a session on {day} at {time}, in Room {room}, with {person}. Visitors are asked to bring their {item}. Anyone unable to attend should contact the office before {deadline}, allowing the place to be offered to another person.\n\nTwo options are available: the {opt1} or the {opt2}. {trade} The coordinator argues that offering both routes gives users more control. A volunteer agrees that choice matters, but warns that publishing options alone does not ensure everyone can use them. People may need help understanding the instructions or comparing the practical consequences.\n\nThe organisation plans to review the arrangements after six weeks. It will count completed appointments and ask users whether they received the help they needed. It will also ask people who did not complete a booking what prevented them from doing so.'
  if n==5:text+=f'\n\nA draft newsletter describes the trial as “a clear success” because completed appointments increased. However, it gives neither the size of the increase nor the number of people who tried to book. This limits the claim: a higher total could reflect greater demand rather than easier access. Comments from satisfied visitors would add useful detail, but would not represent people unable to use either route.\n\nBefore making the arrangements permanent, the review panel should compare completion rates, describe how feedback was collected and examine whether particular groups encountered repeated barriers. The available information supports further investigation; it does not establish that one option is suitable for everyone.'
 factual=[mc('When is the session?',f'{day} at {time}',[f'{day} at 18:00','Sunday at 08:00'],f'The information gives {day} at {time}.'),mc('What should you bring?',f'Your {item}',['A passport photograph','A bank statement'],f'The information asks for your {item}.'),mc('Where should you go?',f'Room {room}',[f'Room {room+1}',f'Room {room+2}'],f'The session is in Room {room}.'),mc('Who can help you?',person,['Chris','Pat'],f'The named contact is {person}.')]
 if n>=2:factual += [mc('What is the purpose of this information?',purpose,['To announce that the organisation has closed.','To advertise a job vacancy.'],f'The text explains the arrangements to {action}.'),mc('Why should you contact the office if you cannot attend?','So that the place can be offered to someone else.',['So the session moves to another room.','So you can avoid bringing a reference.'],'Cancelling gives the office time to offer the place to another person.')] if n>=3 else [mc('What should you do first?',f'Speak to {person}.',['Leave without checking your details.','Wait for the office to call you.'],f'The instructions say to speak to {person} first.')]
 if n>=4:factual += [mc('Which statement is an opinion?','Offering both routes gives users more control.',[f'The session is on {day}.','The review is planned after six weeks.'],'The coordinator is expressing a judgement about the benefit of the options.'),mc('Why ask people who did not complete a booking?','To find barriers that successful users may not report.',['To exclude criticism from the review.','To prove that all users prefer the same option.'],'Feedback only from successful users would miss people who could not access the service.')]
 if n==5:factual += [mc('Why is the newsletter’s claim of success uncertain?','It omits the size of the increase and the number who tried to book.',['It reports that the office has closed.','It says nobody attended.'],'Without the total number attempting to book, an increased count does not establish improved access.'),mc('Which evidence would best test improved access?','Completion rates and feedback from people facing barriers.',['Only the coordinator’s positive opinion.','A list of room numbers.'],'Rates and evidence from unsuccessful users address access more directly than a positive opinion.')]
 # Rotate factual focus across stages; every answer is explicitly grounded in the supplied text.
 offset=(stage-1)%len(factual); tasks=(factual[offset:]+factual[:offset])[:4 if n<3 else 5]
 target=[25,55,90,150,220][n-1]
 checks=['I included the key information.','I checked names, dates and times.','I used sentences appropriate to the task.']
 if n>=3:checks+=['I organised my ideas and explained my reasons.']
 if n>=4:checks+=['I used an appropriate register and checked paragraphs.']
 if n==5:checks+=['I distinguished evidence from opinion and considered a different view.']
 writing_prompts=[f'Write a message to {person}. Say you want to {action}. Give the day and time.',f'Write to {person} to confirm the session. Say what you will bring and ask one question.',f'Write a message explaining this situation: {problem} Ask for the next step.',f'Compare the {opt1} and the {opt2}. Write to {person} saying which would suit the person in this case, and explain why.',f'Write to {person} explaining that you cannot attend on {day}. Request a different arrangement and explain what support you need.',f'Write a response to the proposed review. Explain what feedback should be collected and why.',f'Write a clear proposal to improve access at {org}. Explain the problem, recommend an action and consider a possible disadvantage.']
 if n==1:writing_prompts=[f'Write three short sentences to {person}: your first name, the day {day}, and the time {time}. Use a fictional name.',f'Copy this sentence with a capital letter and full stop: i will bring my {item}',f'Write a short message saying you cannot come on {day}.',f'Write two sentences choosing the {opt1} or the {opt2}.',f'Write a question asking {person} for help.',f'Write a short reminder: include {day}, {time} and Room {room}.',f'Write a message confirming the session and saying what you will bring.']
 if n==2 and stage>5:writing_prompts[stage-1]=f'Write to {person} about your plan to {action}. Explain the steps in order, give the day and time and ask a question.'
 spoken=f'{person}: Hello. Your session to {action} is on {day} at {time}. Please go to Room {room} and bring your {item}.\nVisitor: What should I do if I cannot attend?\n{person}: Please contact the office before {deadline}. We can offer the place to someone else.'
 if n>=3:spoken+=f'\nVisitor: I need to choose between the {opt1} and the {opt2}.\n{person}: {trade}\nVisitor: Thank you. I will consider which option gives me the support I need.'
 if n>=4:spoken+=f'\nVisitor: How will you know if the arrangements are effective?\n{person}: We will review completed appointments and feedback after six weeks.\nVisitor: Please include people who could not complete a booking. Their experiences could show problems that other users did not encounter.'
 if n==5:spoken+='\nVisitor: The newsletter calls the trial a success, but does it provide completion rates?\n'+person+': No. It only says completed appointments increased.\nVisitor: Then we should be cautious. More bookings might reflect higher demand. We need both the number of attempts and evidence about barriers before reaching a conclusion.'
 if sec=='Reading':
  tasks += [reflection(['Find one important word in the text. Write it and explain what it tells you.','Explain the instructions in your own words.','Explain why checking the written summary could matter.','Explain which option would suit the person in the case and support your choice.','Suggest a practical improvement and give a reason.','Identify evidence that would help judge whether the arrangements work.','Summarise the main message and explain what you would do next.'][stage-1],f'A relevant response uses details from the text. For example: {trade}' if n>=2 else f'Include an accurate detail such as {day}, {time}, Room {room}, or {item}.')]
  if n==1: tasks[-1]=reflection(['Write the name of the place.','Write the day and time.','Write what you should bring.','Write the room number.','Write the name of the person who can help.','Write one useful word from the notice.','Write a short reminder using a detail from the notice.'][stage-1],f'Check your answer against the notice: {org}; {day} at {time}; Room {room}; {item}; {person}.')
  material=text
 elif sec=='Writing':
  prompt=writing_prompts[stage-1]+f' Aim for about {target} words; this is a practice guide, not an official assessment word limit.'
  model=f'Dear {person},\n\nI would like to {my_action}. I can attend on {day} at {time} and will bring my {item}. Please confirm that I should go to Room {room}.\n\nThank you,\nAlex'
  if n>=3:model=f'Dear {person},\n\n{problem} I would like to {my_action} and would appreciate some advice about the arrangements.\n\nI have considered the {opt1} and the {opt2}. {trade} The most suitable choice should take account of the support I need as well as travel and timing.\n\nPlease confirm whether the session on {day} at {time}, in Room {room}, is available. I will bring my {item}. If a different arrangement would be more suitable, please explain the next step.\n\nKind regards,\nAlex'
  if n>=2:
   preferred=[opt2,opt2,opt2,opt2,opt2,opt1,opt1,opt2,opt2,opt2][topic]
   reason=['I need help checking my changed address','staff can help with my missing card','I need someone to check the correction','I want to explain the fault clearly','I want to speak to the repair team','I would prefer a route without a change','a shorter route would suit me','I would benefit from supervised practice','I work on weekdays','I do not have reliable internet access'][topic]
   greeting=f'Dear {person},\n\n'
   ending='\n\nKind regards,\nAlex'
   models=[f'I would like to {my_action}. I can attend on {day} at {time} in Room {room}. I will bring my {item}. Please confirm the arrangements.',f'Thank you for offering a session on {day} at {time}. I will bring my {item}. Is there anything else I should prepare before I come?',f'{problem} Please explain the steps I should take to {my_action}. I can bring my {item} if that helps you find the correct record.',f'I have considered both options and would prefer the {preferred} because {reason}. {trade} Please let me know how I can arrange this option.',f'I cannot attend on {day} at {time}. Could you offer another appointment or explain a suitable alternative? {problem} I would appreciate help making a new arrangement.',f'The review should ask both people who completed bookings and people who could not book for feedback. Completed appointments alone do not explain whether users received the support they needed. Comparing the number of successful bookings with the number of attempts would help the panel judge access more fairly.',f'I recommend keeping both booking routes and giving clear information about the help available. {problem} In this case, the {preferred} would be useful because {reason}. Maintaining both routes may need more staff time, so the organisation should monitor demand as well as user feedback before making a permanent decision.']
   model=greeting+models[stage-1]+ending
  if n==1: model=[f'My name is Alex. I can come on {day}. I will come at {time}.',f'I will bring my {item}.',f'Hello {person}. I cannot come on {day}.',f'I choose the {opt1}. Please help me.',f'Can you help me, {person}?',f'Remember: {day}, {time}, Room {room}.',f'Hello {person}. I can come on {day} at {time}. I will bring my {item}.'][stage-1]
  tasks=[reflection('Plan: who are you writing to, why, and which details will you include?',f'Audience: {person} at {org}. Purpose: {action}. Select relevant details from the case.'),reflection(prompt,model),reflection('Edit your draft. Describe one correction you made and why it improves your writing.','Check that your response meets the task, then check sentence boundaries, spelling and appropriate language.')]
  material=text
 else:
  material=spoken
  tasks=[t for t in tasks if t['kind']=='choice' and t['prompt'] in ['When is the session?','What should you bring?','Where should you go?','Who can help you?']]
  if len(tasks)<3:tasks=factual[:4]
  # Listening keys above use only facts repeated in the spoken script.
  tasks=factual[:4]
  tasks+=[reflection(f'Speaking practice: act as the visitor. Explain why you want to {action}, ask a question and confirm the next step. '+('Compare the options and respond to a different view.' if n>=3 else 'Use short, clear sentences.'),f'Include {day}, {time} and your {item}. Ask a relevant question. '+(f'Explain a choice using these facts: {trade}' if n>=3 else f'For example: “Hello, can you help me {my_action}?”')),reflection('Record or rehearse your reply, then note one thing to improve. If practising with a partner, ask for feedback.','Check clarity, relevant information, listening and turn-taking. A recording or typed plan cannot automatically verify spoken competence.')]
 out={k:old[k] for k in ['lesson_id','number','stage_lesson','section','stage']}
 out['key_language']=', '.join([person,day,time,f'Room {room}',item]) if n==1 else ', '.join([title.lower(),'confirm','arrange','reference','option','support','review'])
 out.update(title=f'{title} · {STAGES[stage-1]}',topic=title,learner_material=material,question=tasks[0]['prompt'],answer='',choices=[],tasks=tasks,stage_goal=STAGES[stage-1],learn=f'{LEVELS[n-1]} practice: {STAGES[stage-1].lower()}. '+['Find names, times and familiar words. Read each short line slowly.','Look for the purpose, sequence words and reasons. Use the surrounding words to check meaning.','Follow connected information. Explain a reason and check what an instruction requires.','Separate facts from opinions, compare options and organise a clear response for the audience.','Evaluate claims and evidence, consider different views and use precise language to justify a conclusion.'][n-1],success_check=checks,independent_task=tasks[-1]['prompt'],independent_resource=material,evidence_status='Educational practice. Open writing and speaking responses need human review; completion is not a qualification or verified skill result.')
 return out
for n in range(1,6):
 file=ROOT/f'esol/{n}/assets/lessons.json';original=json.loads(file.read_text());result=[]
 for old in original:
  result.append(build(n,int(old['stage']),int(old['stage_lesson'])-1,old['section'],old))
 file.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
print('Built 1,050 lessons with explicit task schemas and grounded choice keys.')
